{"path": "/tmp/sv-6cc35a267db9412f867ed99ce96d8380/Components/Board/AddTaskForm.razor", "file_text": "<div class="add-task-form">
    <h4>New Task</h4>
    <div class="form-group">
        <label>Title</label>
        <input type="text" @bind="title" placeholder="Task title" />
    </div>
    <div class="form-group">
        <label>Assignee</label>
        <input type="text" @bind="assignee" placeholder="Assignee name" />
    </div>
    <div class="form-group">
        <label>Priority</label>
        <select @bind="priority">
            <option value="High">High</option>
            <option value="Medium">Medium</option>
            <option value="Low">Low</option>
        </select>
    </div>
    <div class="form-group">
        <label>Due Date</label>
        <input type="date" @bind="dueDate" />
    </div>
    @if (!string.IsNullOrEmpty(error))
    {
        <p class="form-error">@error</p>
    }
    <div class="form-actions">
        <button class="btn btn-save" @onclick="HandleSave" disabled="@isSaving">
            @(isSaving ? "Saving…" : "Save")
        </button>
        <button class="btn btn-cancel" @onclick="HandleCancel" disabled="@isSaving">Cancel</button>
    </div>
</div>

@code {
    [Parameter, EditorRequired]
    public string DefaultStatus { get; set; } = "To Do";

    [Parameter]
    public EventCallback<TaskItem> OnTaskCreated { get; set; }

    [Parameter]
    public EventCallback OnCancel { get; set; }

    private string title = string.Empty;
    private string assignee = string.Empty;
    private string priority = "Medium";
    private DateTime dueDate = DateTime.Today.AddDays(7);
    private bool isSaving;
    private string? error;

    [Inject]
    private ITaskService TaskService { get; set; } = default!;

    private async Task HandleSave()
    {
        error = null;

        if (string.IsNullOrWhiteSpace(title))
        {
            error = "Title is required.";
            return;
        }

        if (string.IsNullOrWhiteSpace(assignee))
        {
            error = "Assignee is required.";
            return;
        }

        isSaving = true;
        try
        {
            var created = await TaskService.CreateTaskAsync(title.Trim(), assignee.Trim(), priority, dueDate);
            await OnTaskCreated.InvokeAsync(created);
        }
        catch (Exception ex)
        {
            error = $"Failed to create task: {ex.Message}";
        }
        finally
        {
            isSaving = false;
        }
    }

    private async Task HandleCancel()
    {
        await OnCancel.InvokeAsync();
    }
}
"}

