{"path": "/tmp/sv-6cc35a267db9412f867ed99ce96d8380/Components/Board/KanbanColumn.razor", "file_text": "<div class="kanban-column">
    <div class="column-header">
        <h3>@Title <span class="column-count">(@Tasks.Count)</span></h3>
    </div>

    <div class="column-body">
        @if (Tasks.Count == 0)
        {
            <p class="empty-message">No tasks</p>
        }

        @foreach (var task in Tasks)
        {
            <TaskCard Task="task"
                      ShowMoveLeft="ColumnIndex > 0"
                      ShowMoveRight="ColumnIndex < 2"
                      OnMoveLeft="() => HandleMove(task, -1)"
                      OnMoveRight="() => HandleMove(task, 1)"
                      IsMoving="movingTaskId == task.Id" />
        }
    </div>

    @if (showForm)
    {
        <AddTaskForm DefaultStatus="@Title"
                     OnTaskCreated="HandleTaskCreated"
                     OnCancel="() => showForm = false" />
    }
    else
    {
        <button class="btn btn-add" @onclick="() => showForm = true">+ Add Task</button>
    }
</div>

@code {
    private static readonly string[] Statuses = ["To Do", "In Progress", "Done"];

    [Parameter, EditorRequired]
    public string Title { get; set; } = string.Empty;

    [Parameter, EditorRequired]
    public int ColumnIndex { get; set; }

    [Parameter, EditorRequired]
    public List<TaskItem> Tasks { get; set; } = [];

    [Parameter]
    public EventCallback<(int TaskId, string NewStatus)> OnMoveTask { get; set; }

    [Parameter]
    public EventCallback<TaskItem> OnTaskCreated { get; set; }

    private bool showForm;
    private int? movingTaskId;

    private async Task HandleMove(TaskItem task, int direction)
    {
        var newIndex = ColumnIndex + direction;
        if (newIndex < 0 || newIndex > 2) return;

        movingTaskId = task.Id;
        try
        {
            await OnMoveTask.InvokeAsync((task.Id, Statuses[newIndex]));
        }
        finally
        {
            movingTaskId = null;
        }
    }

    private async Task HandleTaskCreated(TaskItem task)
    {
        showForm = false;
        await OnTaskCreated.InvokeAsync(task);
    }
}
"}

